// Extract video IDs from search results or playlist items
const items = $input.all();
const videoIds = [];

for (const item of items) {
  const videoId = item.json.snippet?.resourceId?.videoId || 
                  item.json.id?.videoId || 
                  item.json.id;

  if (videoId && !videoIds.includes(videoId)) {
    videoIds.push(videoId);
  }
}

return videoIds.map(id => ({ json: { videoId: id } }));

// Quality filter and scoring
const video = $json;
const snippet = video.snippet;
const stats = video.statistics;
const contentDetails = video.contentDetails;

// Extract numeric stats
const viewCount = parseInt(stats.viewCount) || 0;
const likeCount = parseInt(stats.likeCount) || 0;
const commentCount = parseInt(stats.commentCount) || 0;

// Parse duration (ISO 8601)
const duration = contentDetails.duration;
const match = duration.match(/PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?/);
const hours = parseInt(match[1]) || 0;
const minutes = parseInt(match[2]) || 0;
const seconds = parseInt(match[3]) || 0;
const totalSeconds = hours * 3600 + minutes * 60 + seconds;

// Quality filters
const minViews = $node["Get Active YouTube Sources"].json["config"]["min_views"] || 1000;
const minDuration = $node["Get Active YouTube Sources"].json["config"]["min_duration"] || 300; // 5 min
const maxDuration = $node["Get Active YouTube Sources"].json["config"]["max_duration"] || 3600; // 60 min

// Apply filters
if (viewCount < minViews) {
  return null; // Skip - not enough views
}

if (totalSeconds < minDuration || totalSeconds > maxDuration) {
  return null; // Skip - duration out of range
}

// Calculate quality score
let qualityScore = 0.3; // Base score

if (viewCount > 0) {
  const engagementRate = (likeCount + commentCount) / viewCount;
  qualityScore += Math.min(engagementRate * 50, 0.4); // Max +0.4 from engagement
}

// Bonus for good duration (10-30 minutes)
if (totalSeconds >= 600 && totalSeconds <= 1800) {
  qualityScore += 0.1;
}

// Bonus for recent upload
const publishedDate = new Date(snippet.publishedAt);
const daysOld = (Date.now() - publishedDate.getTime()) / (1000 * 60 * 60 * 24);
if (daysOld < 30) {
  qualityScore += 0.1;
}

// Bonus for educational indicators
const title = snippet.title.toLowerCase();
const description = (snippet.description || '').toLowerCase();
const educationalKeywords = ['tutorial', 'learn', 'explained', 'guide', 'introduction', 'course', 'lecture'];

const hasEducationalKeywords = educationalKeywords.some(keyword => 
  title.includes(keyword) || description.includes(keyword)
);

if (hasEducationalKeywords) {
  qualityScore += 0.1;
}

qualityScore = Math.min(qualityScore, 1.0);

// Metadata
const metadata = {
  video_id: video.id,
  channel_id: snippet.channelId,
  channel_name: snippet.channelTitle,
  view_count: viewCount,
  like_count: likeCount,
  comment_count: commentCount,
  tags: snippet.tags || [],
  category_id: snippet.categoryId,
  default_language: snippet.defaultLanguage || 'en',
  topic_categories: video.topicDetails?.topicCategories || [],
  engagement_rate: viewCount > 0 ? ((likeCount + commentCount) / viewCount).toFixed(4) : 0
};

return {
  json: {
    external_id: video.id,
    content_type: 'video',
    source: 'youtube',
    category_id: $node["Get Active YouTube Sources"].json["category_id"],
    title: snippet.title,
    description: snippet.description,
    url: `https://www.youtube.com/watch?v=${video.id}`,
    thumbnail_url: snippet.thumbnails.high?.url || snippet.thumbnails.default?.url,
    author: snippet.channelTitle,
    published_at: snippet.publishedAt,
    duration: totalSeconds,
    language: snippet.defaultLanguage || 'en',
    quality_score: qualityScore.toFixed(2),
    popularity_score: viewCount,
    metadata: metadata
  }
};

// Auto-tag based on content analysis
const video = $json;
const title = video.title.toLowerCase();
const description = (video.description || '').toLowerCase();
const metadata = video.metadata;

const tags = [];

// Difficulty level
if (title.includes('beginner') || title.includes('introduction') || title.includes('basics')) {
  tags.push('beginner-friendly');
} else if (title.includes('advanced') || description.includes('advanced')) {
  tags.push('advanced');
}

// Content type
if (title.includes('tutorial') || description.includes('step by step')) {
  tags.push('tutorial');
}
if (title.includes('lecture') || description.includes('lecture')) {
  tags.push('lecture');
}
if (title.includes('documentary')) {
  tags.push('documentary');
}
if (title.includes('interview')) {
  tags.push('interview');
}

// Educational markers
if (title.includes('explained') || description.includes('explanation')) {
  tags.push('analysis');
}
if (title.includes('guide')) {
  tags.push('guide');
}

video.tags = tags;
return { json: video };

// Aggregate results for logging
const items = $input.all();

const summary = {
  total_sources: items.length,
  total_videos: items.reduce((sum, item) => sum + parseInt(item.json.videos_processed || 0), 0),
  successful: items.filter(item => item.json.result.startsWith('Added')).length,
  failed: items.filter(item => item.json.result === 'Failed').length,
  timestamp: new Date().toISOString()
};

return { json: summary };
